action.code:
if (!root) {
    root = new TreeNode(item);
    return;
}

if (item < root->value) {
    avlInsert(root->left, item);
} else if (item > root->value) {
    avlInsert(root->right, item);
} else {
    return; // Duplicate, do nothing
}

// Update balance factor
root->bFactor = getBalance(root);

// Left heavy
if (root->bFactor > 1) {
    if (root->left->bFactor > 0) {
        // Left-Left case
        rotateRight(root);
    } else {
        // Left-Right case
        rotateLeft(root->left);
        rotateRight(root);
    }
}
// Right heavy
else if (root->bFactor < -1) {
    if (root->right->bFactor < 0) {
        // Right-Right case
        rotateLeft(root);
    } else {
        // Right-Left case
        rotateRight(root->right);
        rotateLeft(root);
    }
}

